<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {onBeforeRouteLeave,useRoute,useRouter} from 'vue-router'
import {message,Modal} from 'ant-design-vue'
import {supplementApi,supplementBusinessStatus,type SupplementDetail,type SupplementSection,type SupplementMaterial,type SupplementFile} from '@/api/supplement'
import {downloadAuthenticatedFile} from '@/utils/authFile'
import FieldInput from './FieldInput.vue'
import SupplementImport from './SupplementImport.vue'
const route=useRoute(),router=useRouter(),detail=ref<SupplementDetail>(),active=ref(''),loading=ref(false),busy=ref(false),error=ref(''),dirty=ref(false),inspector=ref(window.innerWidth>=1250),onlyMissing=ref(false),opinion=ref(''),issues=ref<string[]>([])
const id=computed(()=>String(route.params.id)),current=computed(()=>detail.value?.sections.find(s=>s.key===active.value))
const previewOpen=ref(false),previewUrl=ref(''),previewKind=ref(''),previewText=ref('')
const relatedRow=ref<number>(),snapshot=ref<Record<string,any>>(),snapshotOpen=ref(false)
const actionText=(action:string)=>({SAVE:'保存草稿',UPLOAD:'上传附件',SUBMIT:'提交审核',APPROVE:'审核通过',RETURN:'退回补充',REOPEN:'开启新批次',UNIT_APPROVE:'单位审核通过',HQ_APPROVE:'总部审核通过'}[action]||action)
const stageText=(stage:string)=>({BASIC:'基本信息',DECLARE:'立项准备 · 申报',FILING:'立项准备 · 备案',IMPLEMENT:'实施推进',ACCEPT:'验收闭环',TRANSFORM:'成果转化'}[stage]||stage)
const required=(item:{required?:boolean;requiredWhen?:{field:string;value:any};requiredWhenAll?:{field:string;value:any}[]},row:Record<string,any>)=>!!item.required||!!(item.requiredWhenAll?.length&&item.requiredWhenAll.every(c=>row[c.field]===c.value))||!!(item.requiredWhen&&row[item.requiredWhen.field]===item.requiredWhen.value)
const editable=computed(()=>!!current.value?.canEdit&&route.query.view!=='review'&&route.query.view!=='history')
const stages=computed(()=>Array.from(new Set(detail.value?.sections.map(s=>s.stage)||[])))
const shownMaterials=computed(()=>current.value?.materials.filter(m=>!onlyMissing.value||!m.files?.length)||[])
const statusText=(s:string)=>({DRAFT:'待补录',PENDING:'审核中',SUBMITTED:'审核中',IN_REVIEW:'审核中',UNIT_REVIEW:'单位审核中',HQ_REVIEW:'总部审核中',APPROVED:'已通过',RETURNED:'已退回',REJECTED:'已退回'}[s]||s||'待补录')
async function load(){loading.value=true;error.value='';try{detail.value=(await supplementApi.detail(id.value)).data;for(const s of detail.value.sections){s.values ||= {};s.rows ||= [];s.materials ||= [];s.fields ||= []}if(!current.value)active.value=detail.value.sections[0]?.key||'';dirty.value=false;issues.value=[]}catch(e:any){error.value=e.message;message.error(e.message)}finally{loading.value=false}}
watch(id,load,{immediate:true})
function confirmDiscard():Promise<boolean>{if(!dirty.value)return Promise.resolve(true);return new Promise(resolve=>Modal.confirm({title:'当前内容尚未保存',content:'离开后将丢失本次未保存的修改。',okText:'放弃修改',cancelText:'继续填写',onOk:()=>resolve(true),onCancel:()=>resolve(false)}))}
async function select(key:string){if(key===active.value)return;if(await confirmDiscard()){if(dirty.value)await load();active.value=key;relatedRow.value=undefined;issues.value=[];opinion.value=''}}
onBeforeRouteLeave(()=>confirmDiscard())
function beforeUnload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}
window.addEventListener('beforeunload',beforeUnload);onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeUnload))
function validate(s:SupplementSection){const result:string[]=[];const records=s.repeatable?s.rows:[s.values];if(s.repeatable&&!records.length&&s.requiredRows)result.push('请添加记录；不适用事项请按填写要求说明。');records.forEach((row,index)=>s.fields.forEach(f=>{if(required(f,row)&&(row[f.key]===undefined||row[f.key]===null||String(row[f.key]).trim()===''))result.push(`${s.repeatable?`第 ${index+1} 行 · `:''}${f.label}未填写`)}));s.materials.forEach(m=>{if((required(m,s.values)||s.rows.some(row=>required(m,row)))&&!m.files?.length)result.push(`缺少材料：${m.name}`)});issues.value=result;return result}
async function save(){if(!current.value||!editable.value)return false;busy.value=true;try{await supplementApi.save(id.value,current.value);await load();message.success('草稿已保存');return true}catch(e:any){message.error(e.message);return false}finally{busy.value=false}}
async function submit(){if(!current.value)return;if(validate(current.value).length){inspector.value=true;message.warning('请先完善右侧列出的缺失项');return}Modal.confirm({title:`提交“${current.value.title}”审核`,content:'提交后本次信息和附件版本将锁定，审核期间不能修改。',okText:'确认提交',onOk:async()=>{if(dirty.value&&!(await save()))return;busy.value=true;try{await supplementApi.submit(id.value,current.value!);await load();message.success('已提交审核')}catch(e:any){message.error(e.message)}finally{busy.value=false}}})}
async function audit(action:string){if(!current.value)return;if(!opinion.value.trim()){message.warning('请填写审核意见');return}busy.value=true;try{await supplementApi.audit(id.value,current.value,action,opinion.value);await load();opinion.value='';message.success(action==='APPROVE'?'审核已通过':'已退回负责人补充')}catch(e:any){message.error(e.message)}finally{busy.value=false}}
async function upload(event:Event,m:SupplementMaterial){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file||!current.value)return;if(file.size>100*1024*1024){message.warning('单个附件不能超过 100 MB');input.value='';return;}if(current.value.repeatable&&relatedRow.value===undefined){message.warning('请先选择附件关联的业务记录');input.value='';return}if(dirty.value&&!(await save())){input.value='';return}const rowId=current.value.repeatable?current.value.rows[relatedRow.value!]?._rowId:undefined;if(current.value.repeatable&&!rowId){message.warning('请先保存对应业务记录');input.value='';return}busy.value=true;try{await supplementApi.upload(id.value,current.value,m.code,file,rowId);await load();message.success('材料上传成功，已保留文件版本')}catch(e:any){message.error(e.message)}finally{busy.value=false;input.value=''}}
async function reopen(){if(!current.value)return;busy.value=true;try{await supplementApi.reopen(id.value,current.value);await load();message.success('已开启新补录批次，原审核版本保留')}catch(e:any){message.error(e.message)}finally{busy.value=false}}
async function showSnapshot(historyId:number){try{snapshot.value=(await supplementApi.snapshot(id.value,historyId)).data.snapshot;snapshotOpen.value=true}catch(e:any){message.error(e.message)}}
function rowLabel(row:Record<string,any>,index:number){return `记录 ${index+1} · ${row.name||row.organization||row.year||row.level||row.recordType||row.role||row.status||'未命名'}`}
async function download(file:SupplementFile){try{await downloadAuthenticatedFile(supplementApi.fileUrl(id.value,file.id),file.name||file.fileName)}catch(e:any){message.error(e.message)}}
async function downloadLegacy(file:Record<string,any>){try{await downloadAuthenticatedFile(`/api/supplement/${id.value}/legacy-files/${encodeURIComponent(file.id)}`,file.fileName)}catch(e:any){message.error(e.message)}}
async function previewFile(file:SupplementFile){try{const token=localStorage.getItem('rpm_token');const response=await fetch(supplementApi.fileUrl(id.value,file.id),{headers:token?{Authorization:`Bearer ${token}`}:{}});if(!response.ok)throw new Error('附件预览失败，请确认查看权限');const blob=await response.blob();if(previewUrl.value)URL.revokeObjectURL(previewUrl.value);const name=file.fileName||file.name||'';previewKind.value=/\.pdf$/i.test(name)?'pdf':/\.txt$/i.test(name)?'text':'image';if(previewKind.value==='text')previewText.value=await blob.text();else previewUrl.value=URL.createObjectURL(new Blob([blob],{type:previewKind.value==='pdf'?'application/pdf':blob.type}));previewOpen.value=true}catch(e:any){message.error(e.message)}}
onBeforeUnmount(()=>{if(previewUrl.value)URL.revokeObjectURL(previewUrl.value)})
const currentHistory=computed(()=>detail.value?.history.filter(h=>!h.sectionKey||h.sectionKey===active.value)||[])
</script>
<template>
  <a-spin :spinning="loading"><div class="supplement-workspace">
    <a-alert v-if="error" :message="error" type="error" show-icon><template #action><a-button @click="load">重试</a-button></template></a-alert>
    <template v-if="detail">
      <header class="project-header"><div><a-button type="link" class="back" @click="router.push(`/supplement/${route.query.view||'mine'}`)">← 返回项目列表</a-button><h1>{{detail.project.name||detail.project.projectName}}</h1><div class="project-meta"><span>{{detail.project.projectNo||detail.project.code||detail.project.projectCode}}</span><span>负责人 {{detail.project.leaderName||detail.project.ownerName||'待核对'}}</span><span>业务状态 {{supplementBusinessStatus(detail.project.stageName||detail.project.status)}}</span></div></div><div class="channel"><small>材料清单依据</small><strong>{{detail.channel.name||detail.channel.code||'渠道待核对'}}</strong><span>全量信息与材料补录</span></div></header>
      <a-alert v-if="!detail.channel.resolved" message="项目来源渠道待核对：专项材料清单不能确定，请联系渠道维护人员核对。" type="warning" show-icon class="channel-warning" />
      <a-collapse v-if="detail.legacyMaterials?.length" style="margin-bottom:12px;background:white"><a-collapse-panel key="legacy" :header="'历史材料待归类 · '+detail.legacyMaterials.length+' 份'"><a-alert type="info" message="历史材料已保留，请核对其对应事项；待归类材料暂不计入当前必传清单。" show-icon /><div v-for="file in detail.legacyMaterials" :key="file.id" class="file"><span>{{file.fileName}} · {{file.fieldName||'未分类'}}</span><a-button type="link" @click="downloadLegacy(file)">下载核对</a-button></div></a-collapse-panel></a-collapse><div class="work-grid" :class="{'inspector-hidden':!inspector}">
        <nav class="directory"><div class="directory-title">补录目录 <small>{{detail.sections.length}} 项</small></div><template v-for="stage in stages" :key="stage"><h3>{{stageText(stage)}}</h3><button v-for="s in detail.sections.filter(item=>item.stage===stage)" :key="s.key" :class="{active:s.key===active}" @click="select(s.key)"><span>{{s.title}}</span><small :class="{approved:s.status==='APPROVED'}">{{s.active===false?'不适用 / 未到期':statusText(s.status)}}</small></button></template></nav>
        <main v-if="current" class="editor"><div class="editor-head"><div><h2>{{current.title}}</h2><span class="muted">{{stageText(current.stage)}} · 版本 {{current.version||0}}</span></div><a-button size="small" @click="inspector=!inspector">{{inspector?'收起核查':'展开核查'}}</a-button></div>
          <a-alert v-if="!editable" :message="current.active===false?'当前项目此栏目不适用或尚未到形成时点，内容只读。':current.canAudit?'审核模式：信息及附件只读，请在核查区填写审核意见。':'当前内容只读；审核中及已通过的版本不可修改。'" type="info" show-icon class="readonly-note" />
          <section class="information"><div class="section-heading"><h3>信息填写</h3><SupplementImport v-if="current.repeatable&&editable" :fields="current.fields" :title="current.title" :disabled="busy" @import="current.rows.push(...$event);dirty=true" /><a-button v-if="current.repeatable&&editable" size="small" @click="current.rows.push({});dirty=true">＋ 添加记录</a-button></div>
            <div v-if="current.repeatable" class="records"><a-empty v-if="!current.rows.length" description="暂无记录" /><article v-for="(row,index) in current.rows" :key="index" class="record"><div class="record-title"><strong>记录 {{index+1}}</strong><a-popconfirm v-if="editable" title="移除此条未提交记录？" @confirm="current.rows.splice(index,1);dirty=true"><a-button type="link" danger size="small">移除</a-button></a-popconfirm></div><div class="field-grid"><label v-for="field in current.fields" :key="field.key"><span><i v-if="required(field,row)">*</i>{{field.label}}</span><FieldInput v-model="row[field.key]" :field="field" :disabled="!editable||busy||field.readonly" @update:model-value="dirty=true" /></label></div></article></div>
            <div v-else class="field-grid"><label v-for="field in current.fields" :key="field.key"><span><i v-if="required(field,current.values)">*</i>{{field.label}}</span><FieldInput v-model="current.values[field.key]" :field="field" :disabled="!editable||busy||field.readonly" @update:model-value="dirty=true" /></label></div>
          </section>
          <section class="materials"><div v-if="current.repeatable&&editable" style="margin-bottom:16px"><label class="muted">上传附件关联记录</label><a-select v-model:value="relatedRow" style="width:100%;margin-top:6px" placeholder="先选择对应年度、节点或业务记录" :options="current.rows.map((row,index)=>({value:index,label:rowLabel(row,index)}))" /></div><div class="section-heading"><h3>材料清单 <small>单个附件 ≤ 100 MB · {{current.materials.length}} 项</small></h3><a-checkbox v-model:checked="onlyMissing">仅看缺失</a-checkbox></div><a-empty v-if="!shownMaterials.length" :description="onlyMissing?'暂无缺失材料':'当前项目此项暂无配置附件要求，请完善上述信息'" />
            <article v-for="m in shownMaterials" :key="m.code" class="material"><div class="material-title"><strong>{{m.name}}</strong><a-tag :color="m.required?'orange':'default'">{{m.required?'必传':(m.requiredWhen||m.requiredWhenAll)?'条件必传':'按需补充'}}</a-tag></div><p v-if="m.applicability" class="muted">{{m.applicability}}</p><div class="files"><div v-for="f in m.files" :key="f.id" class="file"><span><small v-if="f.rowId">[{{rowLabel(current.rows.find(row=>row._rowId===f.rowId)||{},current.rows.findIndex(row=>row._rowId===f.rowId))}}] </small>{{f.name||f.fileName}} <small v-if="f.version">v{{f.version}}</small></span><a-button type="link" size="small" @click="download(f)">下载</a-button><a-button v-if="/\.(pdf|png|jpg|jpeg|gif|webp|txt)$/i.test(f.fileName||f.name||'')" type="link" size="small" @click="previewFile(f)">预览</a-button></div><span v-if="!m.files?.length" class="missing">尚未上传</span></div><label v-if="editable" class="upload" :class="{disabled:busy}"><input type="file" :disabled="busy" @change="upload($event,m)" />＋ {{m.files?.length?'补充文件 / 版本':'上传材料'}}</label></article>
          </section>
          <footer class="actions"><span class="muted">{{dirty?'有未保存的修改':'已与服务器同步'}}</span><a-button v-if="current.canReopen&&route.query.view!=='review'&&route.query.view!=='history'" :loading="busy" @click="reopen">开启新补录批次</a-button><div v-if="editable"><a-button :disabled="busy" @click="validate(current);inspector=true">校验当前项</a-button><a-button :loading="busy" @click="save">保存草稿</a-button><a-button v-if="current.active!==false" type="primary" :loading="busy" @click="submit">提交当前项审核</a-button></div></footer>
        </main>
        <aside v-if="inspector&&current" class="inspector"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px"><h3>核查详情</h3><a-button size="small" @click="inspector=false">收起</a-button></div><a-tag>{{statusText(current.status)}}</a-tag><p>来源渠道：{{detail.channel.name||detail.channel.code}}</p><p class="muted">已完成业务仍需补齐历史信息与依据。上传文件不会自动改变业务完成状态。</p><section><h4>适用要求</h4><p>{{current.applicability||'按当前渠道及业务情况填写'}}</p><h4>待完善事项</h4><ul v-if="issues.length||current.missing?.length"><li v-for="issue in (issues.length?issues:current.missing)" :key="issue">{{issue}}</li></ul><p v-else class="muted">点击“校验当前项”核查必填信息和材料，提交时由服务器再次校验。</p></section><section v-if="current.opinion"><h4>审核意见</h4><p>{{current.opinion}}</p></section><section v-if="current.canAudit"><h4>本次审核</h4><a-textarea v-model:value="opinion" placeholder="填写核查意见，退回时说明需补充的内容" :rows="4" /><div class="audit-actions"><a-button danger :loading="busy" @click="audit('RETURN')">退回补充</a-button><a-button type="primary" :loading="busy" @click="audit('APPROVE')">通过</a-button></div></section><section><h4>变更与审核记录</h4><a-empty v-if="!currentHistory.length" description="暂无记录" :image-style="{height:'36px'}" /><div v-for="(h,index) in currentHistory" :key="index" class="history"><strong>{{h.actionText||actionText(h.action||h.status)}}</strong><a-button v-if="h.id" type="link" size="small" @click="showSnapshot(h.id)">查看版本</a-button><p>{{h.opinion||h.comment}}</p><small>{{h.actorName||h.userName}} {{h.createdAt||h.time}}</small></div></section></aside>
      </div>
    </template>
  <a-modal v-model:open="previewOpen" title="附件预览" width="85%" :footer="null"><iframe v-if="previewKind==='pdf'" :src="previewUrl" title="PDF 附件预览" style="width:100%;height:70vh;border:0" /><img v-else-if="previewKind==='image'" :src="previewUrl" alt="附件预览" style="max-width:100%;max-height:70vh" /><pre v-else style="white-space:pre-wrap">{{previewText}}</pre></a-modal><a-modal v-model:open="snapshotOpen" title="历史提交版本 · 只读" width="85%" :footer="null"><template v-if="snapshot"><h3>{{snapshot.title}}</h3><div v-for="(row,index) in (snapshot.repeatable?snapshot.rows:[snapshot.values])" :key="index" class="record"><div class="field-grid"><label v-for="field in snapshot.fields" :key="field.key"><span>{{field.label}}</span><FieldInput :model-value="row[field.key]" :field="field" disabled /></label></div></div><section v-for="m in snapshot.materials" :key="m.code"><h4>{{m.name}}</h4><a-button v-for="f in m.files" :key="f.id" type="link" @click="download(f)">{{f.fileName||f.name}}</a-button></section></template></a-modal></div></a-spin>
</template>
<style scoped>
.supplement-workspace{padding:16px;background:#f3f6fa;min-height:80vh}.project-header{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:14px 20px;background:#fff;border:1px solid #e1e7ee;border-radius:8px;margin-bottom:12px}.back{padding:0;height:24px}h1{font-size:21px;margin:6px 0 8px}h2{font-size:18px;margin:0 0 4px}h3{font-size:14px;margin:0}.project-meta{display:flex;gap:18px;color:#69798c;font-size:12px}.channel{display:flex;flex-direction:column;gap:4px;min-width:160px;border-left:3px solid #176bb8;padding-left:14px}.channel strong{color:#135c9b;font-size:17px}.channel small,.channel span,.muted{color:#758397;font-size:12px}.channel-warning{margin-bottom:12px}.work-grid{display:grid;grid-template-columns:190px minmax(0,1fr) 260px;gap:12px;align-items:start}.work-grid.inspector-hidden{grid-template-columns:190px minmax(0,1fr)}.directory,.editor,.inspector{background:#fff;border:1px solid #e1e7ee;border-radius:6px}.directory{position:sticky;top:12px;padding:12px 8px}.directory-title{font-weight:600;padding:4px 8px 12px;border-bottom:1px solid #edf0f4;display:flex;justify-content:space-between}.directory small{font-size:11px;font-weight:400;color:#8290a0}.directory h3{color:#8a96a5;font-size:11px;margin:14px 8px 5px}.directory button{display:flex;width:100%;align-items:center;justify-content:space-between;text-align:left;gap:4px;border:0;background:transparent;border-radius:4px;padding:10px 8px;cursor:pointer;color:#3f5063;font-size:13px}.directory button.active{background:#eaf3fc;color:#086ac1}.directory .approved{color:#409d57}.editor{min-width:0}.editor-head{padding:16px;display:flex;justify-content:space-between;border-bottom:1px solid #e9edf2}.readonly-note{margin:12px 16px}.information,.materials{padding:16px}.section-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}.section-heading small{font-weight:400;color:#8a96a5;margin-left:6px}.field-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px 16px}.field-grid label>span{display:block;font-size:12px;color:#526173;margin-bottom:5px}.field-grid i{color:#da5151;margin-right:4px;font-style:normal}.record{border:1px solid #e4e9ef;border-radius:5px;padding:12px;margin-bottom:12px}.record-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;font-size:12px}.materials{border-top:1px solid #edf0f4}.material{padding:12px 0;border-bottom:1px solid #edf0f4}.material-title{display:flex;align-items:center;gap:10px;font-size:13px}.files{margin:8px 0}.file{display:flex;justify-content:space-between;align-items:center;background:#f6f8fb;border-radius:4px;padding:4px 8px;margin:5px 0;font-size:12px;gap:10px}.file>span{overflow-wrap:anywhere}.missing{font-size:12px;color:#bd812b}.upload{cursor:pointer;display:inline-block;border:1px solid #adc9e5;border-radius:4px;color:#1265ab;padding:5px 10px;font-size:12px}.upload input{display:none}.upload.disabled{opacity:.5;pointer-events:none}.actions{position:sticky;bottom:0;background:#fff;border-top:1px solid #e2e8f0;display:flex;align-items:center;justify-content:space-between;gap:8px;padding:12px 16px;z-index:2}.actions>div{display:flex;gap:8px}.inspector{padding:16px;position:sticky;top:12px;font-size:12px;max-height:calc(100vh - 130px);overflow:auto}.inspector>h3{margin-bottom:12px}.inspector p{line-height:1.7}.inspector section{border-top:1px solid #e9edf2;margin-top:16px;padding-top:10px}.inspector h4{margin:4px 0 10px}.inspector ul{padding-left:18px;color:#b27625;line-height:1.8}.audit-actions{display:flex;gap:8px;margin-top:10px}.history{border-left:2px solid #d6e4f2;padding-left:10px;margin:12px 0}.history small{color:#8794a3}@media(max-width:1250px){.work-grid{grid-template-columns:170px minmax(0,1fr)}.inspector{position:fixed;right:20px;top:130px;width:290px;z-index:10;box-shadow:0 8px 35px #263c5b33}.work-grid.inspector-hidden{grid-template-columns:170px minmax(0,1fr)}}@media(max-width:800px){.work-grid,.work-gri